import re
ttl = open(GRAPH_TTL).read()
# parse triples simply by lines; build point -> external reference map
# We'll look for the Zone sensor points of interest.
# Find blocks: point line then subsequent property lines until blank.
lines = ttl.splitlines()
# build dict: for each subject gather predicates
d = {}
cur=None
for ln in lines:
    s=ln.strip()
    if not s:
        cur=None; continue
    if s.endswith('.'):
        body=s[:-1]
    else:
        body=s
    # subject = first token
    m=re.match(r'^<([^>]+)>\s+(.*)$',body.strip())
    if m:
        subj=m.group(1); rest=m.group(2)
    else:
        continue
    d.setdefault(subj,[]).append(rest)

